#!/usr/bin/env node
/**
 * generate-atlas-bg.mjs — deterministic generator for `public/atlas-bg.png`.
 *
 * WHY THIS IS A SCRIPT AND NOT A COMMITTED BINARY
 * -----------------------------------------------
 * `Workspace.tsx` composites a full-bleed texture behind the panel stage at 8%
 * opacity with `mix-blend-screen`. The original asset was absent from the
 * repository export, so every page load issued a 404 for `/atlas-bg.png`.
 *
 * Rather than substitute a stock texture, the substrate is generated by this
 * script from a fixed seed. That keeps the artifact honest to the project's own
 * premise — every surface in NEXUS is produced by a seeded generator, so the
 * one bitmap in the pipeline should be too — and it means the texture can be
 * re-derived, re-tuned, and diffed in review instead of being an opaque blob.
 *
 * The output PNG is committed to `public/` so the deployed site does not need
 * Node at build time. Re-run only when the texture is changed:
 *
 *   npm run assets:atlas
 *
 * IMPLEMENTATION
 * --------------
 * Zero dependencies: PNG is emitted by hand (IHDR / IDAT / IEND) over a
 * zlib-deflated scanline buffer. The pixel field is a four-octave value-noise
 * fractal sum, tinted by two radial glows whose positions and colours match the
 * `.bg-cortex` CSS backdrop in `src/styles/base.css` so the layer reads as an
 * extension of the interface rather than an unrelated photograph.
 *
 * Determinism: the same seed and dimensions always produce a byte-identical
 * file, verified by `tests/assets.test.mjs`.
 */

import { deflateSync } from 'node:zlib';
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

/* ------------------------------------------------------------------ config */

const SEED = 20240517; // shared with lib/concepts.ts and lib/vision.ts
const WIDTH = 1280;
const HEIGHT = 800;

/** Matches --color-void in src/styles/tokens.css */
const VOID = [6, 6, 13];

/**
 * Radial glows, deliberately mirrored from the `.bg-cortex` CSS rule so the
 * composited result reinforces the same two colour anchors.
 *   [cx fraction, cy fraction, radius fraction, r, g, b, strength]
 */
const GLOWS = [
  [0.78, 0.08, 0.55, 34, 211, 238, 1.0], // neon cyan — the atlas accent
  [0.12, 0.92, 0.5, 232, 121, 249, 1.0], // flux magenta
  [0.5, 0.5, 0.45, 167, 139, 250, 0.55], // violet core
];

/** Matches the 44px interface grid in `.bg-cortex`. */
const GRID_STEP = 44;
const GRID_STRENGTH = 9;

/* ------------------------------------------------------------- seeded rng */

/** mulberry32 — the same PRNG the application uses (src/lib/rng.ts). */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* ---------------------------------------------------------- value noise */

/**
 * 2D value noise on a seeded integer lattice with smoothstep interpolation.
 * Lattice values are hashed rather than stored, so memory is O(1) in image
 * size and the field tiles seamlessly at `period` cells.
 */
function makeValueNoise(seed, period) {
  const rand = mulberry32(seed);
  const lattice = new Float32Array(period * period);
  for (let i = 0; i < lattice.length; i++) lattice[i] = rand();

  const at = (ix, iy) =>
    lattice[(((iy % period) + period) % period) * period + (((ix % period) + period) % period)];

  const smooth = (t) => t * t * (3 - 2 * t);

  return (x, y) => {
    const x0 = Math.floor(x);
    const y0 = Math.floor(y);
    const fx = smooth(x - x0);
    const fy = smooth(y - y0);
    const a = at(x0, y0);
    const b = at(x0 + 1, y0);
    const c = at(x0, y0 + 1);
    const d = at(x0 + 1, y0 + 1);
    return (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
  };
}

/** Four-octave fractal sum, normalised to roughly 0..1. */
function fbm(noise, x, y, octaves = 4) {
  let sum = 0;
  let amp = 0.5;
  let freq = 1;
  let norm = 0;
  for (let o = 0; o < octaves; o++) {
    sum += noise(x * freq, y * freq) * amp;
    norm += amp;
    amp *= 0.5;
    freq *= 2.07; // non-integer ratio avoids octave aliasing
  }
  return sum / norm;
}

/* ------------------------------------------------------------- png writer */

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let c = 0xffffffff;
  for (let i = 0; i < buf.length; i++) c = CRC_TABLE[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

function chunk(type, data) {
  const len = Buffer.alloc(4);
  len.writeUInt32BE(data.length, 0);
  const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(body), 0);
  return Buffer.concat([len, body, crc]);
}

function encodePng(width, height, rgb) {
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // bit depth
  ihdr[9] = 2; // colour type: truecolour RGB
  ihdr[10] = 0; // compression: deflate
  ihdr[11] = 0; // filter: adaptive
  ihdr[12] = 0; // interlace: none

  // PNG requires every scanline to be prefixed with a filter-type byte.
  const stride = width * 3;
  const raw = Buffer.alloc((stride + 1) * height);
  for (let y = 0; y < height; y++) {
    raw[y * (stride + 1)] = 0; // filter: None
    rgb.copy(raw, y * (stride + 1) + 1, y * stride, y * stride + stride);
  }

  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(raw, { level: 9 })),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

/* ------------------------------------------------------------- renderer */

function render() {
  const noise = makeValueNoise(SEED, 256);
  const fine = makeValueNoise(SEED ^ 0x9e3779b9, 128);
  const rgb = Buffer.alloc(WIDTH * HEIGHT * 3);

  // Spatial frequency expressed in lattice cells across the shorter axis.
  const BASE_CELLS = 5.5;

  for (let y = 0; y < HEIGHT; y++) {
    const vy = y / HEIGHT;
    for (let x = 0; x < WIDTH; x++) {
      const vx = x / WIDTH;

      // Nebulous substrate.
      const n = fbm(noise, vx * BASE_CELLS, vy * BASE_CELLS, 4);
      // High-frequency grain, kept low so it survives 8% compositing.
      // Grain is low-frequency: at 8% compositing, per-pixel noise only costs bytes.
      const grain = fine(vx * 48, vy * 48) - 0.5;

      // Elevation: raises a broad continental shelf so the glows have
      // structure to catch rather than sitting on flat black.
      const shelf = Math.pow(Math.max(0, n - 0.42) / 0.58, 1.6);

      let r = VOID[0] + shelf * 26 + grain * 5;
      let g = VOID[1] + shelf * 30 + grain * 5;
      let b = VOID[2] + shelf * 44 + grain * 6;

      for (const [gx, gy, gr, cr, cg, cb, strength] of GLOWS) {
        const dx = vx - gx;
        const dy = (vy - gy) * (HEIGHT / WIDTH); // correct for aspect
        const d = Math.sqrt(dx * dx + dy * dy) / gr;
        if (d >= 1) continue;
        const fall = Math.pow(1 - d, 2.6) * strength;
        // Glows are modulated by the substrate so they read as volumetric.
        const mod = fall * (0.45 + shelf * 1.4);
        r += cr * mod * 0.34;
        g += cg * mod * 0.34;
        b += cb * mod * 0.34;
      }

      // Interface grid, aligned to the 44px CSS grid.
      const onGrid = x % GRID_STEP === 0 || y % GRID_STEP === 0;
      if (onGrid) {
        r += GRID_STRENGTH * 0.7;
        g += GRID_STRENGTH * 0.75;
        b += GRID_STRENGTH;
      }

      // Vignette — keeps the centre legible under the panel stage.
      const cx = vx - 0.5;
      const cy = vy - 0.5;
      const vig = 1 - Math.min(1, Math.sqrt(cx * cx + cy * cy) * 0.95) * 0.55;
      r *= vig;
      g *= vig;
      b *= vig;

      const o = (y * WIDTH + x) * 3;
      rgb[o] = r < 0 ? 0 : r > 255 ? 255 : r;
      rgb[o + 1] = g < 0 ? 0 : g > 255 ? 255 : g;
      rgb[o + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
    }
  }

  return rgb;
}

/* ----------------------------------------------------------------- main */

const here = dirname(fileURLToPath(import.meta.url));
const outPath = resolve(here, '../public/atlas-bg.png');

mkdirSync(dirname(outPath), { recursive: true });
const png = encodePng(WIDTH, HEIGHT, render());
writeFileSync(outPath, png);

console.log(
  `atlas-bg.png  ${WIDTH}x${HEIGHT}  seed=${SEED}  ${(png.length / 1024).toFixed(1)} KiB  -> ${outPath}`,
);
